  const getCleanWebsite = (url) => {
    if (!url) return 'N/A';
    try {
      const urlObj = new URL(url);
      return urlObj.hostname.replace(/^www\./, '');
    } catch {
      return url.replace(/^https?:\/\//, '').replace(/www\./, '').split('/')[0];
    }
  };

  const getWebsiteHref = (url) => {
    if (!url) return '#';
    if (url.startsWith('http://') || url.startsWith('https://')) {
